import ExternalAuditLog from '../../../models/ExternalAuditLog.js';
import { logger } from '../../../utils/logger.js';
import { retryOperation } from '../../../utils/retryUtils.js';
import NodeCache from 'node-cache';
import { safeJsonStringify } from '../../../utils/jsonUtils.js';

const extLogger = logger.child({ service: 'external-gateway' });
const auditCache = new NodeCache({ stdTTL: 300 });

export function auditLogMiddleware(req, res, next) {
  const startTime = Date.now();

  // Capture request body for POST requests
  let requestBody = null;
  if (req.method === 'POST' && req.body) {
    try {
      requestBody = JSON.stringify(req.body);
    } catch (err) {
      extLogger.warn('Failed to serialize request body for audit log', { error: err.message });
    }
  }

  let responseBody = null;
  let finalized = false;

  // Binary payloads (files, audio, images) are summarised, never stringified: a
  // Buffer through JSON.stringify becomes {"type":"Buffer","data":[…]}, several
  // times its own size, before the model truncates it to 10 KB on save.
  const isTextContentType = () => /^(text\/|application\/(json|[^;]*\+json|xml|javascript|x-www-form-urlencoded))/i
    .test(String(res.getHeader?.('content-type') || ''));

  const serializeResponseBody = (body) => {
    if (body === undefined || body === null) {
      return null;
    }

    if (Buffer.isBuffer(body) || body instanceof Uint8Array) {
      return isTextContentType()
        ? Buffer.from(body).toString('utf8')
        : `[binary ${body.byteLength} bytes]`;
    }

    try {
      return typeof body === 'object'
        ? safeJsonStringify(body)
        : String(body);
    } catch (err) {
      extLogger.warn('Failed to serialize response body for audit log', {
        error: err.message
      });
      return null;
    }
  };

  /**
   * Persist the audit entry exactly once when the response lifecycle completes.
   *
   * @param {string} completionState - Completion state for the request
   * @param {number} statusCode - HTTP status code observed at completion
   */
  const finalizeAuditEntry = (completionState, statusCode = res.statusCode) => {
    if (finalized) return;
    finalized = true;

    const duration = Date.now() - startTime;
    const effectiveStatusCode = Number.isInteger(statusCode) && statusCode > 0
      ? statusCode
      : 500;
    const success = completionState === 'completed' &&
      effectiveStatusCode >= 200 &&
      effectiveStatusCode < 400;

    const auditEntry = {
      timestamp: new Date(),
      method: req.method,
      path: req.originalUrl,
      agentId: req.externalAgentId || null,
      ip: req.ip,
      statusCode: effectiveStatusCode,
      duration,
      paymentTx: req.headers['x-payment-tx'] || null,
      success,
      requestBody,
      responseBody,
      completionState
    };

    // Async save with retry — don't block response
    retryOperation(() => ExternalAuditLog.create(auditEntry), { retries: 3 }).catch(err => {
      extLogger.error('Failed to save audit log after retries:', err);
    });

    extLogger.info(`${req.method} ${req.originalUrl} → ${effectiveStatusCode} (${duration}ms)`, {
      agentId: req.externalAgentId,
      ip: req.ip,
      completionState
    });
  };

  // Capture responses produced by res.send(), including responses generated by res.json().
  const originalSend = typeof res.send === 'function' ? res.send.bind(res) : null;
  if (originalSend) {
    res.send = function (body) {
      if (responseBody === null) {
        responseBody = serializeResponseBody(body);
      }
      return originalSend(body);
    };
  }

  // Wrap res.json to capture response bodies for compatibility with existing callers.
  const originalJson = typeof res.json === 'function' ? res.json.bind(res) : null;
  if (originalJson) {
    res.json = function (body) {
      if (responseBody === null) {
        responseBody = serializeResponseBody(body);
      }
      return originalJson(body);
    };
  }

  // Capture bodies supplied directly to res.end(), while preserving streaming behavior.
  const originalEnd = typeof res.end === 'function' ? res.end.bind(res) : null;
  if (originalEnd) {
    res.end = function (chunk, encoding, callback) {
      if (responseBody === null && chunk !== undefined && chunk !== null) {
        responseBody = serializeResponseBody(chunk);
      }
      return originalEnd(chunk, encoding, callback);
    };
  }

  // finish is emitted for normal responses, including send(), end(), and streaming responses.
  res.once('finish', () => {
    finalizeAuditEntry('completed', res.statusCode);
  });

  // close is emitted when the connection is terminated before the response finishes.
  // Before headers are sent res.statusCode is still Express's default 200, which
  // would record an aborted request as a 200; 499 is the conventional
  // "client closed request" code.
  res.once('close', () => {
    finalizeAuditEntry('aborted', res.headersSent ? res.statusCode : 499);
  });

  next();
}

/**
 * Search audit logs with enhanced filtering capabilities
 * @param {Object} filters - Filter criteria
 * @param {number} page - Page number
 * @param {number} limit - Results per page
 * @returns {Object} Paginated audit logs
 */
export async function searchAuditLogs(filters = {}, page = 1, limit = 20) {
  const cacheKey = `audit_search_${JSON.stringify(filters)}_${page}_${limit}`;
  const cachedResult = auditCache.get(cacheKey);
  if (cachedResult) return cachedResult;

  const query = {};
  
  // Existing filters
  if (filters.method) query.method = filters.method;
  if (filters.path) query.path = { $regex: filters.path, $options: 'i' };
  if (filters.agentId) query.agentId = filters.agentId;
  
  // Enhanced date range filtering
  if (filters.startDate || filters.endDate) {
    query.timestamp = {};
    if (filters.startDate) query.timestamp.$gte = new Date(filters.startDate);
    if (filters.endDate) query.timestamp.$lte = new Date(filters.endDate);
  }
  
  // New filters for enhanced capabilities
  if (filters.minStatusCode || filters.maxStatusCode) {
    query.statusCode = {};
    if (filters.minStatusCode) query.statusCode.$gte = filters.minStatusCode;
    if (filters.maxStatusCode) query.statusCode.$lte = filters.maxStatusCode;
  }
  
  if (filters.minDuration || filters.maxDuration) {
    query.duration = {};
    if (filters.minDuration) query.duration.$gte = filters.minDuration;
    if (filters.maxDuration) query.duration.$lte = filters.maxDuration;
  }
  
  if (filters.ipPattern) {
    query.ip = { $regex: filters.ipPattern, $options: 'i' };
  }
  
  if (filters.success !== undefined) {
    query.success = filters.success;
  }

  const skip = (page - 1) * limit;
  const [logs, total] = await Promise.all([
    ExternalAuditLog.find(query).sort({ timestamp: -1 }).skip(skip).limit(limit).lean(),
    ExternalAuditLog.countDocuments(query)
  ]);

  const result = {
    logs,
    pagination: { page, limit, total, pages: Math.ceil(total / limit) }
  };

  auditCache.set(cacheKey, result);
  return result;
}

/**
 * Export audit logs in specified format
 * @param {Object} filters - Filter criteria
 * @param {string} format - Export format (csv or json)
 * @returns {string} Formatted audit logs
 */
export async function exportAuditLogs(filters = {}, format = 'json') {
  const query = {};
  
  // Apply all available filters
  if (filters.method) query.method = filters.method;
  if (filters.path) query.path = { $regex: filters.path, $options: 'i' };
  if (filters.agentId) query.agentId = filters.agentId;
  
  if (filters.startDate || filters.endDate) {
    query.timestamp = {};
    if (filters.startDate) query.timestamp.$gte = new Date(filters.startDate);
    if (filters.endDate) query.timestamp.$lte = new Date(filters.endDate);
  }
  
  if (filters.minStatusCode || filters.maxStatusCode) {
    query.statusCode = {};
    if (filters.minStatusCode) query.statusCode.$gte = filters.minStatusCode;
    if (filters.maxStatusCode) query.statusCode.$lte = filters.maxStatusCode;
  }
  
  if (filters.minDuration || filters.maxDuration) {
    query.duration = {};
    if (filters.minDuration) query.duration.$gte = filters.minDuration;
    if (filters.maxDuration) query.duration.$lte = filters.maxDuration;
  }
  
  if (filters.ipPattern) {
    query.ip = { $regex: filters.ipPattern, $options: 'i' };
  }
  
  if (filters.success !== undefined) {
    query.success = filters.success;
  }

  // Fetch all matching logs (without pagination)
  const logs = await ExternalAuditLog.find(query).sort({ timestamp: -1 }).lean();
  
  if (format === 'csv') {
    // Create CSV header
    const headers = ['timestamp', 'method', 'path', 'agentId', 'ip', 'statusCode', 'duration', 'success', 'paymentTx'];
    let csvContent = headers.join(',') + '\n';
    
    // Add each log entry as a row
    for (const log of logs) {
      const row = [
        log.timestamp.toISOString(),
        log.method,
        `"${log.path}"`,
        log.agentId || '',
        log.ip,
        log.statusCode,
        log.duration,
        log.success ? 'true' : 'false',
        log.paymentTx || ''
      ].join(',');
      csvContent += row + '\n';
    }
    
    return csvContent;
  } else {
    // Default to JSON format
    return safeJsonStringify(logs, 2);
  }
}

export async function auditLogHealthCheck() {
  try {
    const dbStatus = await ExternalAuditLog.db.db.admin().ping();
    return {
      status: 'healthy',
      database: dbStatus.ok ? 'connected' : 'disconnected',
      cache: auditCache.getStats(),
      timestamp: new Date().toISOString()
    };
  } catch (error) {
    return {
      status: 'unhealthy',
      error: error.message,
      timestamp: new Date().toISOString()
    };
  }
}
